import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as l,o as n,ag as a,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const E=JSON.parse('{"title":"Tailscale 上手教程","description":"Tailscale 让登录同一账号的设备像在同一个局域网里一样互相访问，流量端到端加密，不需要公网 IP 和端口转发。本页带你把两台设备连起来、确认互通、用 Tailscale SSH 连进去，再跑通日常开发的六个场景。","frontmatter":{"title":"Tailscale 上手教程","description":"Tailscale 让登录同一账号的设备像在同一个局域网里一样互相访问，流量端到端加密，不需要公网 IP 和端口转发。本页带你把两台设备连起来、确认互通、用 Tailscale SSH 连进去，再跑通日常开发的六个场景。","domain":"product","tags":["mesh-vpn","remote-access","wireguard","tailscale"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/tailscale/tailscale.md","filePath":"zh/products/tailscale/tailscale.md","lastUpdated":1795592559000}'),o={name:"zh/products/tailscale/tailscale.md"};function d(h,s,p,c,k,g){const t=i("DocDiagram");return n(),l("div",null,[s[0]||(s[0]=a("",29)),r(t,{src:"/diagrams/tailscale-connection.svg",alt:"这张时序图有五条竖向泳道，从左到右是：设备 A、设备 B、身份提供商、协调服务器（控制面）、DERP 中继服务器（同时充当 STUN 服务器）。编号即顺序。第一步，设备 A 和设备 B 各自向身份提供商登录；Tailscale 自己不做用户认证。第二步，两台设备分别向协调服务器上报 MapRequest，内容是自己的节点公钥、地址和候选端点。第三步，协调服务器向设备 A 和设备 B 下发网络地图 netmap，里面有对方是否存在、对方的节点公钥、Tailscale 地址、候选端点和对方的 home DERP 区域；它只下发策略允许看到的节点。第四步，设备 A 连到设备 B 所在的 DERP 服务器，DERP 把连接请求转给设备 B，随后双方经 DERP 交换直连所需的端点信息；经 DERP 的路径画成琥珀色虚线。第五步，双方先用 STUN 查出自己的公网地址，再逐个尝试候选端点做 NAT 穿透；成功就建立直连的 WireGuard UDP 隧道，画成翠绿色粗线，之后数据不再经过第三方。第六步，如果打不通，先尝试 tailnet 内的 Peer Relay，画成青色虚线；Peer Relay 需要显式设置，不是默认就有；没有可用的 Peer Relay，才继续用 DERP 中继，转发的是已加密的 WireGuard 包，画成琥珀色虚线。第七步，设备上的 Tailscale 周期性重试，看能否升级成直连或 Peer Relay。第八步是两条保护标注：协调服务器只分发公钥与策略，不在数据路径上，看不到明文；DERP 只转发已加密的 WireGuard 包，无法解密。直连与回落的区别：直连时数据只在两台设备之间走，不经过第三方；回落时数据经 Peer Relay 或 DERP 中继转发，其中经 DERP 转发的仍是已加密的 WireGuard 包。橙色实线是控制与协商消息。本图省略了：Peer Relay 没有画成单独的一列；WireGuard 握手与密钥协商的内部步骤；NAT 类型与打洞的具体算法；周期性重试的时间间隔；DERP 区域的数量与位置；协调服务器下发策略的具体内容。",width:1020}),s[1]||(s[1]=a("",133))])}const C=e(o,[["render",d]]);export{E as __pageData,C as default};
